/** Dataset-JSON-LD (über das escapende JsonLd). */
function datasetSchema(land, serien, url) {
  const q = land ? `?land=${land}` : "";
  const runden = serien.flatMap((s) => rundenDer(s.id));
  const daten = runden.map((x) => x.datum).sort();
  return {
    "@context": "https://schema.org",
    "@type": "Dataset",
    "@id": `${url}#dataset`,
    name: land ? `Ausschreibungs-Monitor Photovoltaik ${LAND_NAME[land]}` : "Ausschreibungs-Monitor Photovoltaik DACH",
    description:
      "Ergebnisse und Termine der Photovoltaik-Ausschreibungen je Gebotstermin (Volumen, Gebots- und Zuschlagsmenge, mengengewichteter, niedrigster und höchster Zuschlagswert, Höchstwert) aus amtlichen Veröffentlichungen: " +
      serien.map((s) => `${s.name} (${s.land}, ${s.stelle})`).join("; ") +
      ".",
    url,
    inLanguage: "de",
    isAccessibleForFree: true,
    license: MONITOR_LIZENZ.url,
    creator: { "@type": "Organization", name: "ÖkoInvest GmbH", url: abs("/") },
    publisher: { "@id": `${abs("/")}/#organization` },
    isBasedOn: quellenFuer(land).map((x) => x.url),
    spatialCoverage: (land ? [land] : ["DE", "AT", "CH"]).map((l) => ({ "@type": "Place", name: LAND_NAME[l] })),
    temporalCoverage: `${daten[0]}/${daten[daten.length - 1]}`,
    dateModified: MONITOR_STAND,
    keywords: ["Ausschreibung", "Photovoltaik", "Zuschlagswert", "EEG", "EAG-Marktprämie", "Pronovo", "Einmalvergütung", "DACH"],
    variableMeasured: [
      { "@type": "PropertyValue", name: "Mengengewichteter durchschnittlicher Zuschlagswert", unitText: [...new Set(serien.map((s) => s.einheit))].join(", ") },
      { "@type": "PropertyValue", name: "Ausgeschriebene Menge, Gebotsmenge, Zuschlagsmenge", unitText: "MW" },
      { "@type": "PropertyValue", name: "Höchstwert je Gebotstermin", unitText: [...new Set(serien.map((s) => s.einheit))].join(", ") },
    ],
    distribution: [
      { "@type": "DataDownload", encodingFormat: "text/csv", contentUrl: abs(`${DATEI}.csv${q}`) },
      { "@type": "DataDownload", encodingFormat: "application/json", contentUrl: abs(`${DATEI}.json${q}`) },
    ],
  };
}

export default async function AusschreibungenSeite({ params }) {
  const land = await seitenLand(params);
  const sprache = spracheDerAnfrage();
  const en = sprache === "en";
  const t = TEXTE[sprache] || TEXTE.de;
  const heute = new Date();
  const serien = serienFuer(land);
  const termine = termineAm(heute, land);
  const quellen = quellenFuer(land);
  const url = abs(pfad("/marktdaten/ausschreibungen", land, sprache));
  const q = land ? `?land=${land}` : "";
  const standText = datumLang(MONITOR_STAND, en);
  const stellenListe = [...new Set(serien.map((s) => (en ? STELLE_EN[s.stelle] || s.stelle : s.stelle)))];
  const stellen = stellenListe.length > 1 ? `${stellenListe.slice(0, -1).join(", ")} ${en ? "and" : "und"} ${stellenListe.at(-1)}` : stellenListe[0];
  // Für den Browser: nur, was die Anzeige braucht (keine Funktionen), Runden je Reihe
  const serienDaten = serien.map((s) => ({ ...s, runden: rundenDer(s.id) }));
  const quellenDaten = Object.fromEntries(Object.entries(MONITOR_QUELLEN).map(([k, v]) => [k, { titel: v.titel, titelEn: v.titelEn, url: v.url }]));

  return (
    <>
      <JsonLd daten={datasetSchema(land, serien, url)} />

      <Section tone="sand" space="none" className="pb-14 pt-6 sm:pt-8 md:pb-20 md:pt-10">
        <Breadcrumbs items={[{ name: t.wissen, href: "/ratgeber" }, { name: t.marktdaten, href: pfad("/marktdaten") }, { name: t.seite }]} className="mb-8 md:mb-12" />
        <div className="max-w-3xl">
          <Eyebrow>{t.eyebrow(land)}</Eyebrow>
          <h1 className="ov-h1 mt-4 text-balance text-ink-900">{t.titel(land)}</h1>
          <p className="ov-lead mt-5 text-pretty text-ink-600">{t.lead[land || "gemeinsam"]}</p>
          <p className="mt-4 text-[15px] leading-relaxed text-ink-600">{t.lead2}</p>
          <div className="mt-6 flex flex-wrap items-center gap-2">
            <span className="inline-flex items-center gap-1.5 rounded-full bg-sun-50 px-2.5 py-1 text-[12px] font-semibold text-sun-700 ring-1 ring-inset ring-sun-200">
              <Scale aria-hidden="true" className="h-3.5 w-3.5" />
              {t.entwurf}
            </span>
            <span className="text-[13px] text-ink-500">{t.zweit(standText)}</span>
          </div>
          <div className="mt-8 flex flex-col gap-3 sm:flex-row">
            <a href="#monitor" className="inline-flex min-h-11 items-center justify-center gap-2 rounded-2xl bg-ov-600 px-5 py-3 text-[14.5px] font-semibold text-white transition-colors hover:bg-ov-700 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ov-500 focus-visible:ring-offset-2">
              <ArrowDown aria-hidden="true" className="h-4 w-4" />
              {t.zuTerminen}
            </a>
            <a href="#daten" className="inline-flex min-h-11 items-center justify-center gap-2 rounded-2xl bg-white px-5 py-3 text-[14.5px] font-semibold text-ink-800 ring-1 ring-ink-200/70 transition-colors hover:text-navy-700 hover:ring-navy-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ov-500">
              <Download aria-hidden="true" className="h-4 w-4" />
              {t.zuDaten}
            </a>
          </div>
        </div>
      </Section>

      <Section tone="white" space="lg" id="monitor" className="scroll-mt-24">
        <SectionHeading eyebrow={t.monitorEyebrow} title={t.monitorTitel} lead={t.monitorLead[land || "gemeinsam"]} className="mb-10 md:mb-12" />
        <AusschreibungsMonitor serien={serienDaten} termine={termine} quellen={quellenDaten} land={land} />
      </Section>

      <Section tone="sand" space="lg" id="daten" className="scroll-mt-24">
